from fastapi.security import OAuth2PasswordBearer

app = FastAPI(
    openapi_extra={
        "components": {
            "securitySchemes": {
                "OAuth2": {
                    "type": "oauth2",
                    "flows": {
                        "password": {
                            "tokenUrl": "token",
                            "scopes": {}
                        }
                    }
                }
            }
        }
    }
)

@app.get("/")
def read_root():
    return {"Hello": "World"}

if __name__ == "__main__":
    import json
    print(json.dumps(app.openapi(), indent=2))

